// Bulunmayan anahtar sessizce boş dönerse ikon kaybolur ve fark edilmez;
// bu yüzden geliştirmede konsola yazar.
export function ikon(anahtar) {
  const s = IKON[anahtar];
  if (!s) { console.warn('ikon yok:', anahtar); return ''; }
  return s;
}
